// Embeds the toolbar icons (generated by tools/make_icons.py) and the Windows exe icon.
use std::{env, fs, path::Path};

fn main() {
    let manifest = env::var("CARGO_MANIFEST_DIR").unwrap();
    let out = env::var("OUT_DIR").unwrap();
    let dir = Path::new(&manifest).join("assets").join("icons");

    let mut entries: Vec<_> = fs::read_dir(&dir)
        .expect("assets/icons")
        .filter_map(|e| e.ok())
        .map(|e| e.path())
        .filter(|p| p.extension().map_or(false, |x| x == "png"))
        .collect();
    entries.sort();

    let mut code = String::from("pub fn icon_bytes(name: &str) -> Option<&'static [u8]> {\n    match name {\n");
    for p in &entries {
        let stem = p.file_stem().unwrap().to_string_lossy();
        code += &format!("        {:?} => Some(include_bytes!({:?})),\n", stem, p.to_string_lossy());
    }
    code += "        _ => None,\n    }\n}\n";
    fs::write(Path::new(&out).join("icons_gen.rs"), code).unwrap();
    println!("cargo:rerun-if-changed=assets/icons");
    println!("cargo:rerun-if-changed=assets/app.ico");

    #[cfg(windows)]
    {
        let mut res = winresource::WindowsResource::new();
        res.set_icon("assets/app.ico");
        res.set("FileDescription", "Notepad9");
        res.set("ProductName", "Notepad9");
        res.set("LegalCopyright", "Copyright (c) 2026 Notepad9 authors. MIT License.");
        if let Err(e) = res.compile() {
            println!("cargo:warning=exe icon not embedded: {e}");
        }
    }
}
